-- Phase 38F: analytical views for reputation. Internal surveys and imported reviews stay apart, and every rate keeps its denominator.

create view public.fact_cx_feedback with(security_invoker=true) as
 select f.organization_id,f.establishment_id store_id,(f.answered_at at time zone coalesce(e.timezone,'America/Sao_Paulo'))::date metric_date,f.source,f.feedback_type,f.scale,f.is_public,
  count(*) response_count,count(*) filter(where f.score is not null) scored_count,sum(f.score) score_sum,
  count(*) filter(where f.scale='0-10' and f.score>=9) promoters,count(*) filter(where f.scale='0-10' and f.score between 7 and 8.9) passives,count(*) filter(where f.scale='0-10' and f.score<=6) detractors,
  count(*) filter(where f.scale='1-5' and f.score>=4) satisfied
 from public.crm_feedback f join public.establishments e on e.id=f.establishment_id
 where f.answered_at is not null and f.organization_id is not null
 group by f.organization_id,f.establishment_id,(f.answered_at at time zone coalesce(e.timezone,'America/Sao_Paulo'))::date,f.source,f.feedback_type,f.scale,f.is_public;
create view public.fact_cx_survey_responses with(security_invoker=true) as select d.organization_id,d.store_id,date_trunc('day',d.created_at) bucket_at,d.trigger_type,d.channel,d.status,d.skip_reason,count(*) dispatch_count from public.cx_survey_dispatches d group by d.organization_id,d.store_id,date_trunc('day',d.created_at),d.trigger_type,d.channel,d.status,d.skip_reason;
create view public.fact_cx_external_reviews with(security_invoker=true) as select r.organization_id,r.store_id,s.provider,date_trunc('day',r.reviewed_at) bucket_at,count(*) review_count,avg(r.provider_rating) average_rating,count(*) filter(where r.replied_at is not null) replied_count from public.external_reviews r join public.external_review_sources s on s.id=r.source_id group by r.organization_id,r.store_id,s.provider,date_trunc('day',r.reviewed_at);
create view public.fact_cx_review_responses with(security_invoker=true) as select organization_id,store_id,date_trunc('day',created_at) bucket_at,channel,author_type,status,auto_policy,count(*) response_count from public.review_responses group by organization_id,store_id,date_trunc('day',created_at),channel,author_type,status,auto_policy;
create view public.fact_cx_recovery_cases with(security_invoker=true) as select organization_id,store_id,date_trunc('day',created_at) bucket_at,status,outcome,count(*) case_count,count(*) filter(where customer_responded_at is not null) responded_count,count(*) filter(where repurchased_order_id is not null) repurchased_count,count(*) filter(where status not in('resolved','closed','cancelled') and due_at<now()) overdue_count from public.service_recovery_cases group by organization_id,store_id,date_trunc('day',created_at),status,outcome;
create view public.fact_cx_topics with(security_invoker=true) as select organization_id,store_id,date_trunc('day',created_at) bucket_at,topic_key,polarity,origin,count(*) topic_count from public.cx_feedback_topics where removed_at is null group by organization_id,store_id,date_trunc('day',created_at),topic_key,polarity,origin;
create view public.fact_cx_risk_signals with(security_invoker=true) as select organization_id,store_id,date_trunc('day',created_at) bucket_at,signal_type,status,count(*) signal_count from public.cx_risk_signals group by organization_id,store_id,date_trunc('day',created_at),signal_type,status;

do $$declare v text;begin foreach v in array array['fact_cx_feedback','fact_cx_survey_responses','fact_cx_external_reviews','fact_cx_review_responses','fact_cx_recovery_cases','fact_cx_topics','fact_cx_risk_signals'] loop execute format('revoke all on public.%I from public,anon,authenticated',v);execute format('grant select on public.%I to service_role',v);end loop;end$$;
